<script setup lang="ts">
import {computed,onMounted,ref} from 'vue'
import {request} from '../api'
import {newId} from '../ids'
import {clone,type TypeSummary} from '../admin/types'
import {confirmAction} from '../ui/confirm'
const saved=ref<any>(null),config=ref<any>(null),types=ref<TypeSummary[]>([]),templates=ref<any[]>([]),calls=ref<any[]>([]),busy=ref(false),error=ref(''),notice=ref('')
const testType=ref(''),testKeys=new Map<string,string>()
const scope=ref<'global'|'type'|'template'>('global'),scopeKey=ref('')
const dirty=computed(()=>saved.value&&JSON.stringify(saved.value)!==JSON.stringify(config.value))
const rules=computed(()=>{if(!config.value)return null;if(scope.value==='global')return config.value.rules.global_preferences;const table=scope.value==='type'?config.value.rules.content_types:config.value.rules.templates;if(!scopeKey.value)return null;const value=table[scopeKey.value];return Object.hasOwn(table,scopeKey.value)?value:null})
import {preferenceFlags as flags} from './preferences'
async function run(fn:()=>Promise<void>){if(busy.value)return;busy.value=true;error.value='';notice.value='';try{await fn()}catch(e){error.value=e instanceof Error?e.message:String(e)}finally{busy.value=false}}
async function load(){const data=await request('/admin/exchange/settings');saved.value=clone(data);config.value=clone(data);calls.value=(await request('/admin/exchange/ai/calls')).items}
async function save(){await run(async()=>{const {revision,...rest}=config.value;const result=await request('/admin/exchange/settings',{method:'PUT',body:JSON.stringify({...rest,expected_revision:revision})});saved.value=clone(result);config.value=clone(result);notice.value='配置已保存。修改不会重写文章或历史版本。'})}
function reset(){config.value=clone(saved.value);error.value='';notice.value='已取消未保存修改。'}
function addProvider(){if(busy.value||!config.value||config.value.providers.length>=10)return;error.value='';notice.value='';try{config.value.providers.push({id:newId(),name:'新模型',kind:'ollama',base_url:'http://127.0.0.1:11434',model:'',key_env:null,enabled:false,vision:false,max_output_tokens:2048,daily_requests:20,timeout_seconds:60})}catch(e){error.value=e instanceof Error?e.message:String(e)}}
function enableScope(){if(!scopeKey.value)return;const table=scope.value==='type'?config.value.rules.content_types:config.value.rules.templates;table[scopeKey.value]={}}
function setRule(key:string,event:Event){const value=(event.target as HTMLSelectElement).value;if(value==='')delete rules.value[key];else rules.value[key]=value==='true'}
async function testConnection(provider:any){
 if(!testType.value||dirty.value||!provider.enabled||!await confirmAction('向所选模型发送当前类型格式规范及一段合成测试文字，可能计费。不发送文章或照片，不创建文章。继续吗？'))return
 await run(async()=>{const fingerprint=provider.id+':'+config.value.revision+':'+testType.value;let key=testKeys.get(fingerprint);if(!key){key=newId();testKeys.set(fingerprint,key)}
 const result=await request('/admin/exchange/ai/generate',{method:'POST',body:JSON.stringify({request_key:key,provider_id:provider.id,expected_config_revision:config.value.revision,type_slug:testType.value,action:'generate',title:'合成连接测试',display_date:'2000-01-01',materials:'仅使用合成测试内容，测试日期2000-01-01。不编造真实经历。',body:'',consent:true})})
 notice.value=result.state==='succeeded'?'测试响应与格式解析成功；未创建文章。'+(result.replayed?'本次复用原请求结果。':''):('测试状态：'+result.state+'；请核对调用记录，不会自动重试模型。');calls.value=(await request('/admin/exchange/ai/calls')).items
 })
}
async function cancelCall(id:string){await run(async()=>{await request('/admin/exchange/ai/calls/'+id+'/cancel',{method:'POST'});calls.value=(await request('/admin/exchange/ai/calls')).items;notice.value='已请求取消；等待响应或超时，不能保证服务端停止计费。'})}
async function abandonCall(id:string){if(!await confirmAction('仅在请求超时且状态无法确认时使用。模型仍可能已计费，放弃后旧结果不会自动应用；不会自动重新调用。确认标记状态未知？'))return;await run(async()=>{await request('/admin/exchange/ai/calls/'+id+'/abandon',{method:'POST',body:JSON.stringify({confirmation:'确认状态未知'})});calls.value=(await request('/admin/exchange/ai/calls')).items})}
async function openJob(id:string,event:Event){event.preventDefault();if(dirty.value&&!await confirmAction('配置有未保存修改，放弃修改并打开候选？'))return;sessionStorage.setItem('lj-exchange-job',id);window.location.assign('/admin/import')}
async function restoreRules(){if(!await confirmAction('恢复当前作用域的默认规则？不会修改任何文章。'))return;if(scope.value==='global')config.value.rules.global_preferences={};else if(scopeKey.value)delete (scope.value==='type'?config.value.rules.content_types:config.value.rules.templates)[scopeKey.value]}
onMounted(()=>void run(async()=>{await load();types.value=await request('/admin/content/types');templates.value=await request('/admin/templates')}))
</script>
<template><main class="container ai-admin"><header><p class="eyebrow">WRITING PREFERENCES</p><h1>AI 与写作规则</h1><p>AI 完全可选。不配置模型也能导出 ChatGPT 规范并导入图文包。此处不接收或显示完整 API Key。</p></header><p v-if="error" class="error" role="alert">{{error}}</p><p v-if="notice" role="status">{{notice}}</p><p v-if="busy" role="status">正在处理…</p><template v-if="config"><div class="actions ai-save"><span>{{dirty?'有未保存修改':'已保存配置'}} · 修订 {{config.revision}}</span><button :disabled="busy||!dirty" @click="save">保存配置</button><button class="quiet" :disabled="busy||!dirty" @click="reset">取消修改</button></div>
<section class="card"><h2>模型服务</h2><label>默认写作模型<select v-model="config.default_provider" :disabled="busy"><option :value="null">第一个启用模型（调用前仍需确认）</option><option v-for="provider in config.providers" :key="provider.id" :value="provider.id">{{provider.name}}{{provider.enabled?'':'（停用）'}}</option></select></label><label>连接测试使用的内容类型<select v-model="testType" :disabled="busy"><option value="">请选择允许发送格式定义的类型</option><option v-for="type in types.filter(t=>t.active)" :key="type.id" :value="type.slug">{{type.name}}</option></select></label><p>连接测试只发送所选类型规范和合成文字，不发送文章或照片；可能消耗服务配额。</p><p>OpenAI 兼容服务使用 HTTPS。Ollama 内网访问须先由服务端配置精确的允许 Origin；默认禁止访问内网和环回地址。</p><article v-for="provider in config.providers" :key="provider.id" class="ai-provider"><div class="ai-fields"><label>显示名称<input v-model="provider.name" maxlength="80" :disabled="busy"></label><label>服务类型<select v-model="provider.kind" :disabled="busy"><option value="openai">OpenAI 兼容</option><option value="ollama">本地 Ollama</option></select></label><label>Base URL<input v-model="provider.base_url" type="url" :disabled="busy" placeholder="https://example.com/v1"></label><label>Model ID<input v-model="provider.model" maxlength="200" :disabled="busy"></label><label>密钥环境变量引用<input :value="provider.key_env||''" :disabled="busy" placeholder="LJ_AI_KEY_PRIMARY" @input="provider.key_env=($event.target as HTMLInputElement).value||null"></label><label>超时（秒）<input v-model.number="provider.timeout_seconds" type="number" min="5" max="120" :disabled="busy"></label><label>最大输出 Token<input v-model.number="provider.max_output_tokens" type="number" min="64" max="16384" :disabled="busy"></label><label>24小时调用上限<input v-model.number="provider.daily_requests" type="number" min="1" max="1000" :disabled="busy"></label></div><div class="actions"><label><input v-model="provider.enabled" type="checkbox" :disabled="busy">启用模型</label><label><input v-model="provider.vision" type="checkbox" :disabled="busy">服务具备视觉能力（不会自动发送照片）</label><button type="button" class="quiet" :disabled="busy||dirty||!provider.enabled||!testType" @click="testConnection(provider)">测试 / 核对连接</button></div></article><button class="quiet" :disabled="busy||config.providers.length>=10" @click="addProvider">添加模型配置</button></section>
<section class="card"><h2>分层写作偏好</h2><p>全局 → 内容类型 → 模板 → 单次写作。偏好不能关闭权限、媒体验证、草稿保护或真实字段校验；日期不明确时只提示，不编造。</p><div class="actions"><label>作用域<select v-model="scope" :disabled="busy" @change="scopeKey=''"><option value="global">全局默认</option><option value="type">指定内容类型</option><option value="template">指定模板</option></select></label><label v-if="scope!=='global'">稳定配置对象<select v-model="scopeKey" :disabled="busy"><option value="">请选择</option><option v-for="item in scope==='type'?types:templates" :key="item.id" :value="item.slug">{{item.name}}</option></select></label><button v-if="scope!=='global'&&scopeKey&&!rules" class="quiet" :disabled="busy" @click="enableScope">为此对象自定义规则</button></div><div v-if="rules" class="ai-fields"><label v-for="[key,label] in flags" :key="key">{{label}}<select :value="key in rules?String(rules[key]):''" :disabled="busy" @change="setRule(key,$event)"><option value="">继承上一层 / 系统默认</option><option value="true">启用</option><option value="false">关闭</option></select></label><label class="ai-style">文风（留空可继承）<textarea :value="rules.style||''" rows="3" maxlength="4000" :disabled="busy" @input="($event.target as HTMLTextAreaElement).value?rules.style=($event.target as HTMLTextAreaElement).value:delete rules.style"/></label></div><button class="quiet" :disabled="busy" @click="restoreRules">恢复当前作用域默认</button></section>
<section class="card"><h2>最近调用</h2><p>统计只保留模型、状态和服务返回的 Token 数，不保存完整提示词或模型密钥。未知用量不表示免费。取消也不能保证服务端停止计费。</p><p v-if="!calls.length">尚无模型调用。</p><ul><li v-for="call in calls" :key="call.id">{{call.model}} · {{call.action}} · {{call.state}} · {{call.usage_known?`输入 ${call.input_tokens} / 输出 ${call.output_tokens} Token`:'用量未知'}}<span v-if="call.error_code"> · {{call.error_code}}</span><a v-if="call.job_id" href="/admin/import" @click="openJob(call.job_id,$event)">打开留存候选（未自动应用）</a><template v-if="['running','reserved'].includes(call.state)"><button type="button" class="quiet" :disabled="busy" @click="cancelCall(call.id)">请求取消调用</button><button type="button" class="quiet" :disabled="busy" @click="abandonCall(call.id)">放弃并标记状态未知</button></template></li></ul></section></template></main></template>
<style scoped>
.ai-admin{max-width:1160px}.ai-admin>header{display:block}.ai-admin>.card{padding:clamp(16px,3vw,28px);margin-block:20px}.ai-fields{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(100%,240px),1fr));gap:16px}.ai-style{grid-column:1/-1}.ai-provider{border-top:1px solid var(--ui-line);padding-block:20px}.ai-admin label{display:block}.ai-admin input[type=checkbox]{width:auto}.ai-admin textarea{width:100%;box-sizing:border-box}.ai-save{position:sticky;top:0;background:var(--ui-card);padding:16px;z-index:1;flex-wrap:wrap}.ai-admin li{overflow-wrap:anywhere}
</style>
